function filterClassDropdown() {
    filterConfig = window.scsDashFilterConfig || filterConfig;
    var classEl = document.getElementById(filterConfig.classId);
    var options = filterConfig.classOptions || [];
    var scienceId = getSelectValue(filterConfig.scienceId);
    var courseId = getSelectValue(filterConfig.courseId);
    var currentVal;
    var i;

    if (!classEl) {
        return;
    }

    currentVal = classEl.value;

    while (classEl.options.length > 0) {
        classEl.remove(0);
    }

    var defaultOpt = document.createElement("option");
    defaultOpt.value = "";
    defaultOpt.text = "--Chọn--";
    classEl.appendChild(defaultOpt);

    var hasCurrent = false;
    for (i = 0; i < options.length; i++) {
        if (isFilterValueActive(scienceId) && options[i].scienceId !== scienceId) {
            continue;
        }
        if (isFilterValueActive(courseId) && options[i].courseId !== courseId) {
            continue;
        }
        var opt = document.createElement("option");
        opt.value = options[i].id;
        opt.text = options[i].name;
        if (options[i].id === currentVal) {
            opt.selected = true;
            hasCurrent = true;
        }
        classEl.appendChild(opt);
    }

    if (!hasCurrent) {
        classEl.selectedIndex = 0;
    }
}

