        private void FilterClass()
        {
            string strCondition = null;
            if (ddlScienceID.SelectedIndex > 0)
                strCondition = " And ScienceID = '" + ddlScienceID.SelectedValue + "'";
            if (ddlCourseID.SelectedIndex > 0)
                strCondition += " And CourseID = '" + ddlCourseID.SelectedValue + "'";

            strCondition += " And ClassType = 0";

            if (strCondition != null)
                strCondition = strCondition.Substring(5);

            DataTable dtbClass;
            if (Session[SESSION_CLASS_TABLE] != null)
                dtbClass = Session[SESSION_CLASS_TABLE] as DataTable;
            else
                dtbClass = new SIM_ClassDAO().Search("@IsActived", 1);

            WebGlobal.InitDropDownList(ddlClassID, dtbClass, SIM_Class.C_CLASSID, SIM_Class.C_CLASSNAME, "--Chọn--", strCondition);
        }

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                if (ddlClassID.Items.Count == 0)
                    LoadData();
            }
        }

        protected void ddlScienceID_SelectedIndexChanged(object sender, EventArgs e)
        {
            FilterClass();
        }
    }
}

